                              .toList(),
                          onChanged: (val) {
                            if (val != null) setState(() => _selectedParokiId = val);
                          },
                          emptyMessage: 'Paroki tidak ditemukan pada keuskupan ini',
                        ),

                        // 3. Provinsi
                        SearchableSelectField<int>(
                          label: 'Provinsi',
                          icon: Icons.map_rounded,
                          value: _selectedProvinsiId,
                          enabled: !_isSameParish,
                          items: _provinsiList
                              .map((item) => SearchableSelectItem<int>(
                                    value: int.parse(item['id'].toString()),
                                    label: item['name'].toString(),
                                  ))
                              .toList(),
                          onChanged: (val) {
                            if (val != null) _onProvinsiChanged(val);
                          },
                          emptyMessage: 'Provinsi tidak ditemukan',
                        ),

                        // 4. Kota / Kabupaten
                        SearchableSelectField<int>(
                          label: 'Kota / Kabupaten',
                          icon: Icons.location_city_rounded,
                          value: _selectedKabupatenKotaId,
                          enabled: !_isSameParish,
                          items: _kabupatenKotaList
                              .map((item) => SearchableSelectItem<int>(
                                    value: int.parse(item['id'].toString()),
                                    label: item['name'].toString(),
                                  ))
                              .toList(),
                          onChanged: (val) {
                            if (val != null) setState(() => _selectedKabupatenKotaId = val);
                          },
                          emptyMessage: 'Kota tidak ditemukan pada provinsi ini',
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ),

            // ── Sticky Bottom Submit Bar ──
            Container(
              padding: const EdgeInsets.fromLTRB(20, 14, 20, 20),
              decoration: BoxDecoration(
                color: Colors.white,
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.06),
                    blurRadius: 16,
                    offset: const Offset(0, -4),
                  ),
                ],
              ),
              child: SafeArea(
                top: false,
                child: SizedBox(
                  width: double.infinity,
                  height: 52,
                  child: ElevatedButton(
                    onPressed: _isLoading ? null : _submit,
                    style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFF1E5399),
                      disabledBackgroundColor:
                          const Color(0xFF1E5399).withOpacity(0.5),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14),
                      ),
                      elevation: 2,
                      shadowColor: const Color(0xFF1E5399).withOpacity(0.35),
                    ),
                    child: _isLoading
                        ? const SizedBox(
                            height: 22,
                            width: 22,
                            child: CircularProgressIndicator(
                                color: Colors.white, strokeWidth: 2.5),
                          )
                        : const Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              Icon(Icons.send_rounded,
                                  color: Colors.white, size: 18),
                              SizedBox(width: 8),
                              Text(
                                'BUAT PERMINTAAN PELAYANAN',
                                style: TextStyle(
                                  color: Colors.white,
                                  fontSize: 14,
                                  fontWeight: FontWeight.bold,
                                  letterSpacing: 0.5,
                                ),
                              ),
                            ],
                          ),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

